    #[test]
    fn test_predb_validate_filename_candidate_rules() {
        let title = b"Canonical.Release-GRP";
        let fname = b"C:\\directory\\Alias.Release-GRP.rar";
        let src = b"srrdb";
        let id = unsafe {
            nntmux_predb_validate_filename_candidate(
                b"07".as_ptr(),
                2,
                0,
                0,
                title.as_ptr(),
                title.len(),
                fname.as_ptr(),
                fname.len(),
                src.as_ptr(),
                src.len(),
            )
        };
        assert_eq!(id, 7);

        // Forbidden title separator
        let bad_title = b"bad/title";
        let id_bad = unsafe {
            nntmux_predb_validate_filename_candidate(
                std::ptr::null(),
                0,
                7,
                1,
                bad_title.as_ptr(),
                bad_title.len(),
                std::ptr::null(),
                0,
                std::ptr::null(),
                0,
            )
        };
        assert_eq!(id_bad, 0);

        // Control character U+200B in filename
        let zwsp_fname = "/bad\u{200B}directory/Alias.rar".as_bytes();
        let id_zwsp = unsafe {
            nntmux_predb_validate_filename_candidate(
                std::ptr::null(),
                0,
                7,
                1,
                title.as_ptr(),
                title.len(),
                zwsp_fname.as_ptr(),
                zwsp_fname.len(),
                std::ptr::null(),
                0,
            )
        };
        assert_eq!(id_zwsp, 0);
    }

