        fn call(entry: Entry, records: &[&[u8]]) -> Vec<i64> {
            let data = records.join(&0u8);
            let mut out = vec![0i64; 4096];
            let written = unsafe {
                entry(
                    records.len(),
                    0,
                    data.as_ptr(),
                    data.len(),
                    std::ptr::null(),
                    0,
                    out.as_mut_ptr(),
                    out.len(),
                )
            };
            assert!(written >= 0, "declined: {written}");
            out.truncate(written as usize);
            out
        }

